// Expect { jobId } in body; tolerate raw string body
const raw = $json.body ?? $json;
const body = (typeof raw === 'string') ? JSON.parse(raw) : raw;
const jobId = body.jobId;
if (!jobId) throw new Error('Missing required field: jobId');
return [{ json: { jobId } }];

// Collect rows into byType map
const rows = $input.all().map(i => i.json);
const byType = {};
for (const r of rows) byType[r.type] = r.content;

const proj = $('Resolve Project (jobId)').first().json;
const jobId = $('Parse Input').first().json.jobId;
const projectSlug = proj.slug;
const projectName = proj.name || proj.slug;

const required = ['prd_md','brd','archimate_xml_business_application_data_infra'];
const missing = required.filter(t => !byType[t]);
if (missing.length) throw new Error('Missing required artifacts: ' + missing.join(', '));

return [{ json: { jobId, projectSlug, projectName, byType } }];

// Build git script using stable context (avoid $json overwrites from SSH nodes)
const ctx = $('Collect Artifacts').first().json;
const jobId = ctx.jobId;
const projectSlug = ctx.projectSlug;

const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';

const remote = 'git@github.com:shlapolosa/software-delivery.git';
const byType = ctx.byType || {};

const files = [];
const fullXml = (byType.archimate_xml_business_application_data_infra || {}).xml || '';
files.push({ path: repoDir + '/org-architecture/full.archimate', content: fullXml });

const bizXml = (byType.archimate_xml_business || {}).xml || '';
const appXml = (byType.archimate_xml_business_application || {}).xml || '';
const dataXml = (byType.archimate_xml_business_application_data || {}).xml || '';
const techXml = fullXml;

if (bizXml) files.push({ path: projectDir + '/architecture/business.archimate', content: bizXml });
if (appXml) files.push({ path: projectDir + '/architecture/application.archimate', content: appXml });
if (dataXml) files.push({ path: projectDir + '/architecture/data.archimate', content: dataXml });
if (techXml) files.push({ path: projectDir + '/architecture/technology.archimate', content: techXml });
if (techXml) files.push({ path: projectDir + '/architecture/full.archimate', content: techXml });

files.push({ path: projectDir + '/docs/BRD.md', content: $('Render BRD.md').first().json.brdMarkdown || '' });
files.push({ path: projectDir + '/docs/PRD.md', content: (byType.prd_md || {}).markdown || '' });

const risk = (byType.risk_assessment_md || {}).markdown;
if (risk) files.push({ path: projectDir + '/docs/risk-assessment.md', content: risk });
const sol = (byType.solution_arch_md || {}).markdown;
if (sol) files.push({ path: projectDir + '/docs/solution-architecture.md', content: sol });
const ts = (byType.test_strategy_md || {}).markdown;
if (ts) files.push({ path: projectDir + '/docs/test-strategy.md', content: ts });
const sc = (byType.test_scenarios_md || {}).markdown;
if (sc) files.push({ path: projectDir + '/docs/test-scenarios.md', content: sc });

const openapi = (byType.openapi_yaml || {}).yaml;
if (openapi) files.push({ path: projectDir + '/api/openapi.yaml', content: openapi });
const asyncapi = (byType.asyncapi_yaml || {}).yaml;
if (asyncapi) files.push({ path: projectDir + '/api/asyncapi.yaml', content: asyncapi });
const ce = (byType.cloudevents_md || {}).markdown;
if (ce) files.push({ path: projectDir + '/api/cloudevents.md', content: ce });
const avro = (byType.avro_schemas_json || {}).schemas;
if (avro) files.push({ path: projectDir + '/api/avro-schemas.json', content: JSON.stringify(avro, null, 2) });
const sql = (byType.sql_schema_sql || {}).sql;
if (sql) files.push({ path: projectDir + '/db/schema.sql', content: sql });

const mkdirs = [
  repoDir + '/org-architecture',
  projectDir + '/docs',
  projectDir + '/api',
  projectDir + '/db',
  projectDir + '/architecture',
  projectDir + '/backlog',
];

let sh = '';
sh += 'set -e\n';
sh += 'mkdir -p /opt/workspace\n';
sh += "if [ ! -d '" + repoDir + "/.git' ]; then git clone '" + remote + "' '" + repoDir + "'; fi\n";
sh += "cd '" + repoDir + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin\n';
sh += "git checkout -B '" + projectSlug + "' 'origin/" + projectSlug + "' 2>/dev/null || git checkout -B '" + projectSlug + "'\n";
sh += mkdirs.map(d => "mkdir -p '" + d + "'").join('\n') + '\n';

for (const f of files) {
  sh += "cat > '" + f.path + "' <<'EOF_" + jobId + "'\n";
  sh += (f.content || '') + "\nEOF_" + jobId + "\n";
}

sh += "git add org-architecture '" + projectSlug + "-docs'\n";
sh += "git commit -m 'Add artifacts for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push -u origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, gitScript: sh } }];

// Build task-master script using stable context
const ctx = $('Collect Artifacts').first().json;
const jobId = ctx.jobId;
const projectSlug = ctx.projectSlug;

const remote = 'git@github.com:shlapolosa/software-delivery.git';

const repoDirHost = '/opt/workspace/software-delivery';

// taskmaster container sees /local-ai-packaged/projects via bind mount
const repoDirHostForContainer = '/local-ai-packaged/projects/software-delivery';
const projectDirHostForContainer = repoDirHostForContainer + '/' + projectSlug + '-docs';
const projectDirContainer = '/app/projects/software-delivery/' + projectSlug + '-docs';

let sh = '';
sh += 'set -e\n';

// Ensure repo in /opt/workspace
sh += "if [ ! -d '" + repoDirHost + "/.git' ]; then git clone '" + remote + "' '" + repoDirHost + "'; fi\n";
sh += "cd '" + repoDirHost + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += 'git fetch origin\n';
sh += "git checkout '" + projectSlug + "'\n";

// Sync into compose-mounted path (prefer rsync, fallback to cp)
sh += "mkdir -p '" + repoDirHostForContainer + "'\n";
sh += "if command -v rsync >/dev/null 2>&1; then\n";
sh += "  rsync -a --delete '" + repoDirHost + "/' '" + repoDirHostForContainer + "/'\n";
sh += "else\n";
sh += "  rm -rf '" + repoDirHostForContainer + "'\n";
sh += "  mkdir -p '" + repoDirHostForContainer + "'\n";
sh += "  cp -a '" + repoDirHost + "/.' '" + repoDirHostForContainer + "/'\n";
sh += "fi\n";

// Validate PRD exists
sh += "test -d '" + projectDirHostForContainer + "'\n";
sh += "test -f '" + projectDirHostForContainer + "/docs/PRD.md'\n";

sh += "docker ps --no-trunc | grep -w taskmaster\n";
sh += "docker exec taskmaster task-master --help >/dev/null 2>&1\n";

// Init + parse
sh += "docker exec -w '" + projectDirContainer + "' taskmaster task-master init -y || true\n";
sh += "docker exec -w '" + projectDirContainer + "' taskmaster task-master parse-prd --input='docs/PRD.md' --num-tasks=15\n";

// Iterative complexity-based expansion (max 5 iterations)
sh += "for i in 1 2 3 4 5; do\n";
sh += "  echo \"=== Expansion iteration $i ===\"\n";
sh += "  docker exec -w '" + projectDirContainer + "' taskmaster task-master analyze-complexity || true\n";
sh += "  docker exec -w '" + projectDirContainer + "' taskmaster task-master expand --all --force || break\n";
sh += "done\n";

// Final complexity analysis for story point estimation
sh += "docker exec -w '" + projectDirContainer + "' taskmaster task-master analyze-complexity || true\n";

// Copy tasks.json into backlog
sh += "mkdir -p '" + projectDirHostForContainer + "/backlog'\n";
sh += "TASKS_JSON='" + projectDirHostForContainer + "/.taskmaster/tasks/tasks.json'\n";
sh += "COMPLEXITY_JSON='" + projectDirHostForContainer + "/.taskmaster/reports/task-complexity-report.json'\n";
sh += "if [ -f \"$TASKS_JSON\" ]; then cp \"$TASKS_JSON\" '" + projectDirHostForContainer + "/backlog/tasks.json'; fi\n";

// Generate stories.json by merging complexity scores from report
sh += "\n# Generate stories.json from tasks merged with complexity report\n";
sh += "STORIES_OUTPUT='" + projectDirHostForContainer + "/backlog/stories.json'\n";
sh += 'if [ -f "$TASKS_JSON" ]; then\n';
sh += '  if command -v jq >/dev/null 2>&1; then\n';
sh += '    if [ -f "$COMPLEXITY_JSON" ]; then\n';
sh += '      jq -s '\''\n'
      sh += '        (.[1].complexityAnalysis // []) as $complexity |\n'
      sh += '        ($complexity | map({(.taskId | tostring): .complexityScore}) | add // {}) as $scores |\n'
      sh += '        def complexity_to_points: if . <= 3 then 1 elif . <= 5 then 2 elif . <= 7 then 3 elif . <= 9 then 5 else 8 end;\n'
      sh += '        def to_story($scores):\n'
      sh += '          (.id | tostring) as $id |\n'
      sh += '          ($scores[$id] // 5) as $complexity |\n'
      sh += '          {\n'
      sh += '            id: .id,\n'
      sh += '            title: .title,\n'
      sh += '            description: .description,\n'
      sh += '            status: .status,\n'
      sh += '            priority: (.priority // "medium"),\n'
      sh += '            complexityScore: $complexity,\n'
      sh += '            storyPoints: ($complexity | complexity_to_points),\n'
      sh += '            acceptanceCriteria: (if .subtasks and (.subtasks | length) > 0 then [.subtasks[] | "- " + .title] else ["- " + .title + " is implemented", "- Tests pass", "- Code reviewed"] end),\n'
      sh += '            dependencies: (.dependencies // []),\n'
      sh += '            tags: (.tags // []),\n'
      sh += '            subtasks: (if .subtasks then [.subtasks[] | to_story($scores)] else [] end)\n'
      sh += '          };\n'
      sh += '        .[0] | {\n'
      sh += '          projectSlug: "' + projectSlug + '",\n'
      sh += '          generatedAt: (now | strftime("%Y-%m-%dT%H:%M:%SZ")),\n'
      sh += '          complexitySource: "task-complexity-report.json",\n'
      sh += '          totalTasks: ([.tasks[]] | length),\n'
      sh += '          totalLeafTasks: ([.tasks[] | select(.subtasks == null or (.subtasks | length) == 0)] | length),\n'
      sh += '          totalPoints: ([.tasks[] | (($scores[.id | tostring] // 5) | complexity_to_points)] | add),\n'
      sh += '          stories: [.tasks[] | to_story($scores)]\n'
      sh += '        }\n'
      sh += '\''" "$TASKS_JSON" "$COMPLEXITY_JSON" > "$STORIES_OUTPUT"\n';
sh += '    else\n';
sh += '      cp "$TASKS_JSON" "$STORIES_OUTPUT"\n';
sh += '    fi\n';
sh += '  else\n';
sh += '    cp "$TASKS_JSON" "$STORIES_OUTPUT"\n';
sh += '  fi\n';
sh += 'fi\n';

// Commit backlog only (do not commit .taskmaster)
sh += "cd '" + repoDirHostForContainer + "'\n";
sh += "git remote set-url origin '" + remote + "'\n";
sh += "git checkout '" + projectSlug + "'\n";
sh += "git add '" + projectSlug + "-docs/backlog/tasks.json' '" + projectSlug + "-docs/backlog/stories.json' || true\n";
sh += "git commit -m 'Add task-master tasks+stories for " + projectSlug + " (job " + jobId + ")' || true\n";
sh += "git push origin '" + projectSlug + "'\n";

return [{ json: { ...ctx, taskmasterScript: sh } }];

